package com.madar.files;
import android.media.*;
import java.io.*;
import java.nio.*;
import java.util.concurrent.atomic.AtomicBoolean;
final class ExtraAudioEncoder {
 static void encode(File pcm,File output,boolean opus,AtomicBoolean cancel)throws Exception{
  String mime=opus?MediaFormat.MIMETYPE_AUDIO_OPUS:MediaFormat.MIMETYPE_AUDIO_FLAC;int rate=opus?48000:44100;MediaCodec codec=null;MediaMuxer mux=null;boolean started=false;
  try(RandomAccessFile in=new RandomAccessFile(pcm,"r");OutputStream raw=opus?new ByteArrayOutputStream():new BufferedOutputStream(new FileOutputStream(output))){
   MediaFormat format=MediaFormat.createAudioFormat(mime,rate,2);if(opus)format.setInteger(MediaFormat.KEY_BIT_RATE,128000);else format.setInteger(MediaFormat.KEY_FLAC_COMPRESSION_LEVEL,5);format.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,16384);
   codec=MediaCodec.createEncoderByType(mime);codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();if(opus)mux=new MediaMuxer(output.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_OGG);long sourceFrames=pcm.length()/4,total=Math.round(sourceFrames*rate/44100.0),frames=0;boolean endIn=false,endOut=false,wroteConfig=false;int track=-1;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long began=android.os.SystemClock.elapsedRealtime();
   while(!endOut){MusicSeparator.check(cancel);if(android.os.SystemClock.elapsedRealtime()-began>30L*60*1000)throw new IOException("انتهت مهلة ترميز الصوت");if(!endIn){int index=codec.dequeueInputBuffer(10000);if(index>=0){ByteBuffer b=codec.getInputBuffer(index);b.clear();int count=(int)Math.min(total-frames,b.remaining()/4);long pts=frames*1000000L/rate;if(count<=0){codec.queueInputBuffer(index,0,0,pts,MediaCodec.BUFFER_FLAG_END_OF_STREAM);endIn=true;}else{if(opus){long first=(long)(frames*44100.0/rate),last=Math.min(sourceFrames-1,(long)Math.ceil((frames+count)*44100.0/rate));byte[] data=new byte[(int)(last-first+1)*4];in.seek(first*4);in.readFully(data);b.order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<count;i++){double p=(frames+i)*44100.0/rate-first;int a=Math.min(data.length/4-1,(int)p),d=Math.min(data.length/4-1,a+1);double weight=p-a;for(int ch=0;ch<2;ch++){int ai=a*4+ch*2,di=d*4+ch*2;short x=(short)((data[ai]&255)|(data[ai+1]<<8)),y=(short)((data[di]&255)|(data[di+1]<<8));b.putShort((short)Math.round(x+(y-x)*weight));}}}else{byte[] data=new byte[count*4];in.readFully(data);b.put(data);}codec.queueInputBuffer(index,0,count*4,pts,0);frames+=count;}}}
    int index=codec.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED&&opus){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;}else if(index>=0){if(info.size>0){ByteBuffer b=codec.getOutputBuffer(index);b.position(info.offset);b.limit(info.offset+info.size);boolean config=(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0;if(opus){if(!config)mux.writeSampleData(track,b,info);}else{byte[] data=new byte[info.size];b.get(data);if(config){if(wroteConfig)throw new IOException("تغيرت تهيئة FLAC أثناء التصدير");if(data.length>=4&&data[0]=='f'&&data[1]=='L'&&data[2]=='a'&&data[3]=='C')raw.write(data);else{if(data.length!=34)throw new IOException("تهيئة FLAC غير معروفة");raw.write(new byte[]{'f','L','a','C',(byte)128,0,0,34});raw.write(data);}wroteConfig=true;}else{if(!wroteConfig)throw new IOException("لم ينتج المرمز ترويسة FLAC");raw.write(data);}}}endOut=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);}}
  }finally{if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}if(mux!=null){try{if(started)mux.stop();}finally{mux.release();}}}
 }
}
